      mascotHappyRef.current+=midGlitch?4:1;
      const cfg=levelCfgRef.current;
      if(cfg){if(gs.score>=cfg.scoreGoal&&(!cfg.modifier||checkModGoal(cfg.modifier,gs))){endLevel(true);return;}}
