      const isFocus=colorIdx===(hit._focusIdx||0);
      const combo=Math.min(10,1+Math.floor(gs.streak/5));
      const feverMult=gs.feverActive?2:1;
      const pts=Math.round((isFocus?800:200)*combo*feverMult);
