      spawnPopup(hit.x,hit.y-28,hasLastTap?`🪞 REFLECTION! +${pts}`:`🌑 DARK MIRROR +${pts}`,hasLastTap?"#f0abfc":"#6b7280",hasLastTap?22:14);
      spawnParticles(hit.x,hit.y,hasLastTap?"#f472b6":"#6b7280",hasLastTap?14:5,"spark");
