      const isMatch=runeIdx===(hit._targetRune||0);
      const combo=Math.min(10,1+Math.floor(gs.streak/5));
      const feverMult=gs.feverActive?2:1;
      const pts=Math.round((isMatch?700:150)*combo*feverMult);
