      spawnPopup(hit.x,hit.y-28,isMatch?`⚡ RUNE MATCH! +${pts}`:`🔮 ARCANE +${pts}`,isMatch?"#ffd700":"#818cf8",isMatch?24:16);
      spawnParticles(hit.x,hit.y,isMatch?"#ffd700":"#818cf8",isMatch?18:6,"spark");
