    setStreakDecaying(false);
    const multSurge=activePwrRef.current.some(p=>p.type==="MULTIPLIER_SURGE"&&p.endsAt>Date.now());
    const combo=Math.min(multSurge?20:10,Math.round((1+Math.floor(gs.streak/5))*(multSurge?2:1)));
