    if(poisonMult<1)gs._poisonedUntil=null; // consume debuff after one hit
    const scoreBoostMult=(gs._scoreBoostTaps||0)>0?5:1;
    if(scoreBoostMult>1){gs._scoreBoostTaps--;if(gs._scoreBoostTaps<=0)setNotif("×5 boost ended!");}
