    unlock("first_tap");
    if(gs.streak>=5)unlock("streak_5");
    if(gs.streak>=10)unlock("streak_10");if(gs.streak>=25)unlock("streak_25");if(gs.streak>=50)unlock("streak_50");
    if(gs.streak>=15)unlock("combo_15");
